import React, { useState, useEffect } from 'react';
import { openDB } from 'idb'; // Import idb for IndexedDB

// IndexedDB setup
const dbName = 'contactsDB';
const storeName = 'contacts';

const openContactsDB = async () => {
  return await openDB(dbName, 1, {
    upgrade(db) {
      if (!db.objectStoreNames.contains(storeName)) {
        const store = db.createObjectStore(storeName, {
          keyPath: 'id', // Assuming each contact will have a unique ID
          autoIncrement: true, // Auto-generate IDs
        });
        store.createIndex('by_name', 'name');
      }
    },
  });
};

const getContactsFromIndexedDB = async () => {
  const db = await openContactsDB();
  return await db.getAll(storeName); // Get all contacts
};

const saveContactToIndexedDB = async (contact) => {
  const db = await openContactsDB();
  return await db.add(storeName, contact); // Add contact to IndexedDB
};

const updateContactInIndexedDB = async (id, updatedContact) => {
  const db = await openContactsDB();
  return await db.put(storeName, { ...updatedContact, id }); // Update contact by ID
};

const deleteContactFromIndexedDB = async (id) => {
  const db = await openContactsDB();
  return await db.delete(storeName, id); // Delete contact by ID
};

function App() {
  const [contacts, setContacts] = useState([]);  // Initialize contacts as an empty array
  const [loading, setLoading] = useState(true);   // Add loading state
  const [newContact, setNewContact] = useState({ name: '', phone: '', email: '', address: '' }); // New contact form
  const [isEditing, setIsEditing] = useState(false);  // State to check if editing
  const [editIndex, setEditIndex] = useState(null);  // Store index of the contact being edited

  // Fetch contacts from IndexedDB when the component mounts
  useEffect(() => {
    const fetchContacts = async () => {
      const fetchedContacts = await getContactsFromIndexedDB(); // Fetch from IndexedDB
      setContacts(fetchedContacts);
      setLoading(false); // Data has finished loading
    };

    fetchContacts();
  }, []);  // Empty dependency array ensures this effect runs only once

  if (loading) {
    return <div>Loading...</div>; // Show loading state while fetching data
  }

  // Handle adding a new contact
  const handleAddContact = () => {
    if (newContact.name && newContact.phone && newContact.email && newContact.address) {
      saveContactToIndexedDB(newContact).then((createdContact) => {
        setContacts([...contacts, createdContact]); // Add the new contact to state
        setNewContact({ name: '', phone: '', email: '', address: '' }); // Reset form
      });
    } else {
      alert('Please fill in all fields.');
    }
  };

  // Handle input change
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setNewContact({ ...newContact, [name]: value });  // Update the specific field in the form state
  };

  // Handle updating an existing contact
  const handleUpdateContact = () => {
    if (newContact.name && newContact.phone && newContact.email && newContact.address) {
      updateContactInIndexedDB(editIndex, newContact).then((updatedContact) => {
        const updatedContacts = contacts.map((c, i) =>
          i === editIndex ? updatedContact : c
        );
        setContacts(updatedContacts);
        setIsEditing(false);  // Stop editing
        setNewContact({ name: '', phone: '', email: '', address: '' }); // Clear form
      });
    } else {
      alert('Please fill in all fields.');
    }
  };

  // Set the form to editing mode with selected contact's details
  const handleEditContact = (index) => {
    setEditIndex(index);
    setNewContact(contacts[index]); // Pre-fill form with contact data
    setIsEditing(true);  // Set editing mode to true
  };

  // Handle deleting a contact
  const handleDeleteContact = (id) => {
    deleteContactFromIndexedDB(id).then(() => {
      const updatedContacts = contacts.filter((_, i) => i !== id);
      setContacts(updatedContacts);
    });
  };

  return (
    <div>
      <h1>Contacts</h1>
      <ul>
        {contacts.map((contact, index) => (
          <li key={contact.id}>
            {contact.name} - {contact.phone} - {contact.email} - {contact.address}
            <button onClick={() => handleEditContact(index)}>Edit</button>
            <button onClick={() => handleDeleteContact(contact.id)}>Delete</button>
          </li>
        ))}
      </ul>

      {/* Form to Add or Update Contact */}
      <div>
        <h2>{isEditing ? 'Edit Contact' : 'Add New Contact'}</h2>
        <form onSubmit={(e) => e.preventDefault()}>
          <input
            type="text"
            name="name"
            value={newContact.name}
            onChange={handleInputChange}
            placeholder="Name"
          />
          <input
            type="text"
            name="phone"
            value={newContact.phone}
            onChange={handleInputChange}
            placeholder="Phone"
          />
          <input
            type="email"
            name="email"
            value={newContact.email}
            onChange={handleInputChange}
            placeholder="Email"
          />
          <input
            type="text"
            name="address"
            value={newContact.address}
            onChange={handleInputChange}
            placeholder="Address"
          />
          <button type="button" onClick={isEditing ? handleUpdateContact : handleAddContact}>
            {isEditing ? 'Update Contact' : 'Add Contact'}
          </button>
        </form>
      </div>
    </div>
  );
}

export default App;
